SINA_SMART["immuno1-anti-infectious"] = {"lecture":"immuno1-anti-infectious","title":"Anti-infectious immunity","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"immuno1-anti-infectious:e0","text":"Routes: ingestion, injection, inhalation, sexual contact.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e1","text":"Levels: prevent entry, eliminate, control multiplication.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e2","text":"Th1 (IL-12, T-bet): intracellular. Th2 (IL-4, GATA-3): extracellular. Th17 (IL-6 + TGF-β, RORγt): fungi. Treg (FoxP3).","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e3","text":"Antiviral: IFN-I (PKR, OAS, Mx), NK, CD8 CTL, neutralising Ab.","topic":"Antiviral immunity","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e4","text":"IFN types: I (α, β), II (γ), III (λ).","topic":"Antiviral immunity","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e5","text":"Extracellular bacteria: Ab, complement, phagocytes. Intracellular: Th1 IFN-γ activates macrophages.","topic":"Antibacterial immunity","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e6","text":"Escape: capsule (pneumococcus), blocked fusion (TB), phagosome lysis (Listeria).","topic":"Antibacterial immunity","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e10","text":"Extracellular → humoral; intracellular → cellular.","topic":"Antiparasitic and antifungal immunity","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e7","text":"Helminths: Th2, IgE, eosinophils (MBP), mast cells.","topic":"Antiparasitic and antifungal immunity","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e8","text":"Parasite escape: antigenic variation (Plasmodium), host proteins (Schistosoma).","topic":"Antiparasitic and antifungal immunity","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"immuno1-anti-infectious:e9","text":"Fungi: alternative complement, Th17/IL-17, neutrophils.","topic":"Antiparasitic and antifungal immunity","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"9sm56a":"a","25phcc":"a","1wv9a8b":"a","xpqn29":"a","mxqsra":"a","1dqb77o":"a","o4wdla":"a","1i1kufl":"a","rvvqzs":"a","68wef0":"a","f4q3sz":"a","jvs9a6":"a","dpul5k":"a","tr0dl6":"a","7l34mz":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"immuno1-anti-infectious:e0":{"s":0,"u":["Routes: ingestion, injection, inhalation, sexual contact.","Microbes enter by ingestion, injection, inhalation or sexual contact ."],"dp":[]},"immuno1-anti-infectious:e1":{"s":0,"u":["Levels: prevent entry, eliminate, control multiplication.","Anti-infectious immunity works on three levels: preventing entry , eliminating the agent quickly and controlling its multiplication , through innate (immediate: barriers, PAMP-PRR recognition, phagocytes, inflammation, NK cells, granulocytes, mast cells) and adaptive immunity (late: CD4 and CD8 T cells, antibodies, memory)."],"dp":[]},"immuno1-anti-infectious:e2":{"s":0,"u":["Th1 (IL-12, T-bet): intracellular. Th2 (IL-4, GATA-3): extracellular. Th17 (IL-6 + TGF-β, RORγt): fungi. Treg (FoxP3).","Dendritic cells polarise naive CD4 T cells: Th1 (IL-12, T-bet, STAT-4 → IFN-γ: intracellular pathogens), Th2 (IL-4, GATA-3, STAT-6: extracellular pathogens, humoral), Th17 (TGF-β + IL-6, RORγt, STAT-3 → IL-17: extracellular pathogens, fungi, inflammation) and Treg (TGF-β, FoxP3: immunosuppression)."],"dp":[]},"immuno1-anti-infectious:e3":{"s":1,"u":["Antiviral: IFN-I (PKR, OAS, Mx), NK, CD8 CTL, neutralising Ab.","Weapons: type I interferons (IFN-α, β) , made by virus-infected cells, which put neighbouring cells into an antiviral state through PKR (blocks viral protein synthesis), 2′5′-oligoadenylate synthetase (degrades viral RNA via RNase L) and Mx protein (blocks viral transcription), and promote apoptosis; NK cells and CD8 cytotoxic T cells , which kill infected cells; and neutralising antibodies , which stop attachment, entry and uncoating of free virus and, on infected cells, drive complement lysis, opsonisation and ADCC ."],"dp":[]},"immuno1-anti-infectious:e4":{"s":1,"u":["IFN types: I (α, β), II (γ), III (λ).","Three IFN families: type I (α, β), type II ( IFN-γ ) and type III (IFN-λ: IL-28A, IL-28B, IL-29)."],"dp":[]},"immuno1-anti-infectious:e5":{"s":2,"u":["Extracellular bacteria: Ab, complement, phagocytes. Intracellular: Th1 IFN-γ activates macrophages.","Intracellular bacteria : Th1 cells release IFN-γ, TNF, IL-2 to activate macrophages, plus lysis of infected cells.","Extracellular bacteria : antibodies (neutralisation of toxins, opsonisation ), complement and phagocytes."],"dp":[]},"immuno1-anti-infectious:e6":{"s":2,"u":["Escape: capsule (pneumococcus), blocked fusion (TB), phagosome lysis (Listeria).","Escape: capsules (Streptococcus pneumoniae) or polysaccharides (Neisseria gonorrhoeae) preventing attachment; enzymes blocking phagosome-lysosome fusion ( Mycobacterium tuberculosis ) or lysing the phagosome ( Listeria monocytogenes ); a very resistant wall ( M. leprae ); lipoarabinomannan of mycobacteria blocking the macrophage response to IFN-γ."],"dp":[]},"immuno1-anti-infectious:e10":{"s":3,"u":["Extracellular → humoral; intracellular → cellular.","Summary: humoral immunity (antibodies, complement, phagocytes, eosinophils) handles extracellular pathogens; cellular immunity (CD8, NK, macrophages, CD4) handles intracellular ones."],"dp":[]},"immuno1-anti-infectious:e7":{"s":3,"u":["Helminths: Th2, IgE, eosinophils (MBP), mast cells.","Parasites : intracellular protozoa → Th1 ; extracellular protozoa → antibodies ; helminths (trematodes, nematodes, cestodes) → Th2 : IL-4 and IL-5 drive IgE , mast cell and eosinophil degranulation ( major basic protein ), ADCC, with hypereosinophilia ."],"dp":[{"h":"Why helminth infections raise eosinophils","t":"Worms are far too large to be phagocytosed. Instead, Th2 cells release IL-4, which switches B cells to IgE, and IL-5, which produces and activates eosinophils. IgE coats the worm, and eosinophils bind it through Fc receptors and release toxic granule proteins such as major basic protein onto its surface. That is why a blood count showing hypereosinophilia prompts a search for parasites. Source: the lecture's anti-parasitic immunity slides."}]},"immuno1-anti-infectious:e8":{"s":3,"u":["Parasite escape: antigenic variation (Plasmodium), host proteins (Schistosoma).","Escape: antigenic variation (Plasmodium), using host proteins such as ABO and HLA ( Schistosoma ), inhibiting the phagosome (Leishmania, Toxoplasma), immunosuppression (Plasmodium, S. mansoni)."],"dp":[]},"immuno1-anti-infectious:e9":{"s":3,"u":["Fungi: alternative complement, Th17/IL-17, neutrophils.","Fungi : wall glycans, polymannans, chitin and zymosan activate epithelial cells, neutrophils, macrophages, dendritic cells and the alternative complement pathway ; Th17 cells (IL-17) boost neutrophil antifungal activity and antimicrobial peptides."],"dp":[]}},"meta":{"9sm56a":{"a":"recall","vg":"immuno1-anti-infectious:e1/recall/1"},"25phcc":{"a":"recall","vg":"immuno1-anti-infectious:e5/recall/1"},"1wv9a8b":{"a":"recall","vg":"immuno1-anti-infectious:e9/recall/1"},"xpqn29":{"a":"recall","vg":"immuno1-anti-infectious:e2/recall/1"},"mxqsra":{"a":"recall","vg":"immuno1-anti-infectious:e4/recall/1"},"1dqb77o":{"a":"recall","vg":"immuno1-anti-infectious:e3/recall/1"},"o4wdla":{"a":"recall","vg":"immuno1-anti-infectious:e3/recall/2"},"1i1kufl":{"a":"recall","vg":"immuno1-anti-infectious:e3/recall/3"},"rvvqzs":{"a":"recall","vg":"immuno1-anti-infectious:e5/recall/2"},"68wef0":{"a":"recall","vg":"immuno1-anti-infectious:e5/recall/3"},"f4q3sz":{"a":"recall","vg":"immuno1-anti-infectious:e6/recall/1"},"jvs9a6":{"a":"recall","vg":"immuno1-anti-infectious:e7/recall/1"},"dpul5k":{"a":"recall","vg":"immuno1-anti-infectious:e8/recall/1"},"tr0dl6":{"a":"recall","vg":"immuno1-anti-infectious:e9/recall/2"},"7l34mz":{"a":"recall","vg":"immuno1-anti-infectious:e10/recall/1"}},"explRev":"3f348a8f1733"};
